#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    int n;
    std::cin >> n;
    std::vector<long long> a(n);
    for (auto &x : a) std::cin >> x;
    long long sum = std::accumulate(a.begin(), a.end(), 0LL,
        [](long long acc, long long x) {
            return x % 2 == 0 ? acc + x * x : acc;
        });
    long long odd = std::count_if(a.begin(), a.end(),
        [](long long x) { return x % 2 != 0; });
    std::cout << sum << "\n" << odd << "\n";
    return 0;
}
